type DeploymentTarget = 'static-export' | 'managed-next' | 'node-self-hosted';

type Requirements = {
  serverActions: boolean;
  runtimeAuth: boolean;
  isr: boolean;
  operationsTeam: boolean;
};

function chooseTarget(input: Requirements): DeploymentTarget {
  const needsServer = input.serverActions || input.runtimeAuth || input.isr;
  if (!needsServer) return 'static-export';
  return input.operationsTeam ? 'node-self-hosted' : 'managed-next';
}

// Portfolio/docs -> static-export
// Fullstack cá nhân, không muốn vận hành -> managed-next
// Cần kiểm soát hạ tầng/network/runtime -> node-self-hosted

// next.config.ts
import type { NextConfig } from 'next';

const mode = process.env.NEXT_OUTPUT ?? 'export';
const output: NextConfig['output'] =
  mode === 'standalone' ? 'standalone' : mode === 'export' ? 'export' : undefined;

const nextConfig: NextConfig = {
  ...(output ? { output } : {}),
  poweredByHeader: false,
  images: {
    // Static export không có image optimizer runtime.
    unoptimized: mode === 'export',
  },
};

export default nextConfig;

// Static:     npm run build (default export)
// Node:       NEXT_OUTPUT=node npm run build
// Standalone: NEXT_OUTPUT=standalone npm run build

// next.config.ts
const repository = process.env.GITHUB_REPOSITORY?.split('/')[1] ?? '';
const isProjectSite =
  process.env.GITHUB_ACTIONS === 'true' &&
  repository !== '' &&
  !repository.endsWith('.github.io');

const basePath = isProjectSite ? `/${repository}` : '';

const nextConfig: NextConfig = {
  output: 'export',
  basePath: basePath || undefined,
  images: { unoptimized: true },
};

// Khi dùng custom domain ở root, đặt NEXT_PUBLIC_BASE_PATH rỗng
// và thêm file public/CNAME chứa domain đã xác minh.

// ecosystem.config.cjs
module.exports = {
  apps: [
    {
      name: 'next-pro',
      cwd: '/srv/next-pro/current',
      script: '.next/standalone/server.js',
      instances: 1,
      exec_mode: 'fork',
      autorestart: true,
      max_memory_restart: '768M',
      min_uptime: '10s',
      max_restarts: 10,
      restart_delay: 2000,
      listen_timeout: 10000,
      kill_timeout: 15000,
      env_production: {
        NODE_ENV: 'production',
        HOSTNAME: '127.0.0.1',
        PORT: '3000',
      },
    },
  ],
};

// Không ghi DATABASE_URL/JWT_SECRET vào file này.
// Inject secret từ server environment hoặc secret manager.

// app/api/health/live/route.ts
import { NextResponse } from 'next/server';
export const dynamic = 'force-dynamic';

export function GET() {
  return NextResponse.json({
    status: 'alive',
    uptimeSeconds: Math.round(process.uptime()),
    timestamp: new Date().toISOString(),
  });
}

// app/api/health/ready/route.ts
export const dynamic = 'force-dynamic';

export async function GET() {
  try {
    await Promise.race([
      db.$queryRaw`SELECT 1`,
      new Promise((_, reject) => setTimeout(() => reject(new Error('timeout')), 1500)),
    ]);
    return NextResponse.json({ status: 'ready' });
  } catch {
    return NextResponse.json({ status: 'not-ready' }, { status: 503 });
  }
}

upstream next_app {
  server 127.0.0.1:3000;
  keepalive 32;
}

server {
  listen 443 ssl http2;
  server_name app.example.com;

  location / {
    proxy_pass http://next_app;
    proxy_http_version 1.1;
    proxy_set_header Host $host;
    proxy_set_header X-Forwarded-Proto $scheme;
    proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;

    # Không gom toàn response trước khi gửi: giữ RSC/PPR streaming.
    proxy_buffering off;
    proxy_read_timeout 60s;
  }

  location = /api/health/live {
    proxy_pass http://next_app;
    access_log off;
  }
}
